/* thong bao ung ho: dem luot bam nut tai (cookie mkd=<so luot>.<luot da nhac>.<cho hien>), hien o luot 2, roi moi 5 luot.
   Web khong biet luc nao tai xong that, nen hien sau 2,5 giay hoac khi nguoi dung quay lai trang. Doi so trong due() de chinh nhip nhac */
(function(){
var CK='mkd',STK='9021870093495',QR='data:image/png;base64,',S={n:0,s:0,p:0};
function rc(){var m=new RegExp('(?:^|; )'+CK+'=([^;]*)').exec(d.cookie||''),a=m?m[1].split('.'):[];S.n=parseInt(a[0],10)||S.n;S.s=parseInt(a[1],10)||S.s;S.p=a[2]==='1'?1:0}
function wc(){try{d.cookie=CK+'='+S.n+'.'+S.s+'.'+S.p+';path=/;max-age=31536000'}catch(e){}}
function due(n){return n>=2&&(n===2||(n-2)%5===0)&&n>S.s}
function isDl(a){var h=a.getAttribute('href')||'';return /(^|\s)dlbtn(\s|$)/.test(a.className||'')||/\/v1\/(j|f)\/|\.(jar|jad|zip)([?#]|$)/i.test(h)}
/* o so tai khoan + nut sao chep (dung chung cho popup va khoi Ung ho co dinh) */
function accBox(){
 var acc=el('div','mkd-acc'),lb=el('label','','Số tài khoản (ngân hàng Timo)'),inp=el('input'),cp=el('button','mkd-btn','Sao chép số tài khoản');
 inp.type='text';inp.value=STK;inp.readOnly=true;inp.onfocus=function(){try{inp.select()}catch(e){}};
 acc.appendChild(lb);acc.appendChild(inp);acc.appendChild(cp);
 function done(ok){cp.textContent=ok?'Đã sao chép':'Chạm giữ vào số để chép';try{inp.focus();inp.select()}catch(e){}}
 function legacy(){var ok=false;try{inp.focus();inp.select();if(inp.setSelectionRange)inp.setSelectionRange(0,STK.length);ok=!!(d.execCommand&&d.execCommand('copy'))}catch(e){}done(ok)}
 cp.type='button';
 cp.onclick=function(){
  if(navigator.clipboard&&navigator.clipboard.writeText){try{navigator.clipboard.writeText(STK).then(function(){done(1)},legacy);return}catch(e){}}
  legacy()};
 return{acc:acc,inp:inp,cp:cp}}
